SELECT id, user_id, student_no, name, gender, age, class_name, major, college, phone, email, address, create_time, update_time
FROM student
WHERE id = #{id}

SELECT id, user_id, student_no, name, gender, age, class_name, major, college, phone, email, address, create_time, update_time
FROM student
WHERE user_id = #{userId}

SELECT id, user_id, student_no, name, gender, age, class_name, major, college, phone, email, address, create_time, update_time
FROM student
WHERE student_no = #{studentNo}

mapper.update:
