user_id = #{userId}, student_no = #{studentNo}, name = #{name}, gender = #{gender}, age = #{age}, class_name = #{className}, major = #{major}, college = #{college}, phone = #{phone}, email = #{email}, address = #{address}, update_time = #{updateTime},
